import type { CSSProperties, ReactNode } from "react";
import "./dither-aperture.css";

interface DitherApertureProps {
  aspectRatio?: CSSProperties["aspectRatio"];
  children: ReactNode;
  className?: string;
  focus?: string;
}

export function DitherAperture({
  aspectRatio = "16 / 9",
  children,
  className = "",
  focus = "70% 38%",
}: DitherApertureProps) {
  const style = {
    "--tb-dither-focus": focus,
    aspectRatio,
  } as CSSProperties;

  return (
    <div className={`tb-dither-aperture ${className}`.trim()} style={style}>
      <div className="tb-dither-aperture__media">{children}</div>
      <div className="tb-dither-aperture__veil" aria-hidden="true" />
    </div>
  );
}

.tb-dither-aperture {
  position: relative;
  isolation: isolate;
  min-inline-size: 0;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: #d8d8d0;
}

.tb-dither-aperture__media {
  position: absolute;
  inset: 0;
}

.tb-dither-aperture__veil {
  position: absolute;
  inset: -2px;
  pointer-events: none;
  background:
    radial-gradient(circle, rgb(20 22 22 / 0.78) 0 1px, transparent 1.2px) 0 0 / 6px 6px,
    radial-gradient(circle, rgb(20 22 22 / 0.44) 0 0.7px, transparent 1px) 3px 3px / 6px 6px,
    rgb(223 222 211 / 0.52);
  -webkit-mask-image: radial-gradient(
    ellipse 45% 52% at var(--tb-dither-focus),
    transparent 0 34%,
    rgb(0 0 0 / 0.18) 49%,
    #000 78%
  );
  mask-image: radial-gradient(
    ellipse 45% 52% at var(--tb-dither-focus),
    transparent 0 34%,
    rgb(0 0 0 / 0.18) 49%,
    #000 78%
  );
}

@media (forced-colors: active) {
  .tb-dither-aperture__veil {
    display: none;
  }
}
